// Method: Restore
(*~
	<docu>
		<summary>
			Restores this instance to the Ready state. Can be called explicitly or from within one of the restore mechanisms.
			<para>
				See also <see cref="PlcDocu.TcoCore.TcoTask.AutoRestorable()"/>
			</para>
		</summary>			
	</docu>	
~*)
METHOD Restore : ITcoRestorable
SUPER^.Restore();
_x := 0.0;
_y := 0.0;
_currentIteration := 0;

PROGRAM MAIN_TECHNOLOGY
VAR
	_technology : Technology;
END_VAR

_technology.Run();

TYPE EC001 :
STRUCT
	{attribute addProperty Name "A1"}
	A1 	: EL1008;
	{attribute addProperty Name "A10"}
	A10 : EL2008;
END_STRUCT
END_TYPE

{attribute 'qualified_only'}
VAR_GLOBAL
	{attribute addProperty Name "EC001"}
	EC001 : EC001;
END_VAR

FUNCTION_BLOCK ST001 EXTENDS TcoCore.TcoObject
VAR	
	{attribute addProperty Name "<#MANUAL#>"}
	_serviceModeTask : TcoCore.TcoTask(THIS^);
    {attribute addProperty Name "<#GROUND#>"}	
	_groundSequenceTask  : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#AUTOMAT#>"}	
	_automatSequenceTask  : TcoCore.TcoTask(THIS^);

	{attribute clr [Container(Layout.Stack)]}
	_components : ST001_ComponentsHandler(THIS^);

	{attribute clr [RenderIgnore()]}
	_mqttMirrorComponents : ST001_ComponentsHandler(THIS^);

	{attribute clr [Container(Layout.Stack)]}
	_groundPositionSequence : ST001_GroundSequence(THIS^, eRestoreMode.None);
	_automatPositionSequence : ST001_AutomatSequence(THIS^, eRestoreMode.None);

	_settings 	: ST001_ProcessDataManager(THIS^);
	_repository : ST001_ProcessDataManager(THIS^);
END_VAR

_components();
_settings();
_repository();
_groundPositionSequence(inoComponents := _components);
_automatPositionSequence(inoComponents := _components);


IF(_groundSequenceTask.Execute()) THEN
	_serviceModeTask.Abort();
	_groundPositionSequence.Run();
	_groundSequenceTask.DoneWhen(_groundPositionSequence.CurrentStep.ID = _groundPositionSequence.MaxStepID - 1);	
END_IF

_automatSequenceTask.Enabled := _groundSequenceTask.Done;

IF(_automatSequenceTask.Execute()) THEN	
	_automatPositionSequence.Run();
END_IF

IF(_serviceModeTask.Execute()) THEN
	_automatSequenceTask.Restore();	
	_groundSequenceTask.Restore();
	_groundPositionSequence.Restore();
	_components.Service();
END_IF

FUNCTION_BLOCK ST001_AutomatSequence EXTENDS TcoCore.TcoSequencer
VAR_IN_OUT
	inoComponents : ST001_ComponentsHandler;	
END_VAR
VAR
	_gTimer_1 : Tc2_Standard.TON;
END_VAR



// Method: Main
(*~
	<docu>
		<summary>
			Main method of the sequener. Custom code needs to be placed here. The sequencer is executed by call of InstanceName.Run() method.
			This method is abstract, and it must be overridden in derived block.
		</summary>
	</docu>
~*)
METHOD PROTECTED  Main : BOOL
IF(NOT __ISVALIDREF(inoComponents)) THEN
	Messenger.Programming('Invalid reference to inoComponents');
	RETURN;
END_IF


IF(Step(inStepID  			:= 100,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#LOAD PART INTO FIXTURE#>')) 
THEN
//---------------------------------------	    
	IF(inoComponents.PartPresent.IsTrue) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= 200,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#PRESS START BUTTON TO START OPERATIONS#>')) 
THEN
//---------------------------------------
	IF(inoComponents._startButton.IsTrue) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= 300,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#PRESSING#>')) 
THEN
//---------------------------------------
	_gTimer_1(IN := inoComponents.Press.MoveToWork().Done, PT := T#500MS);
	IF(_gTimer_1.Q) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= 400,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#MOVING PRESS TO HOME POSITION#>')) 
THEN
//---------------------------------------
	IF(inoComponents.Press.MoveToHome().Done) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= 500,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#REMOVE PART FROM THE FIXTURE#>')) 
THEN
//---------------------------------------
	IF(inoComponents.PartPresent.IsFalse) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= 600,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#SAVE DATA#>')) 
THEN
//---------------------------------------
	IF(THIS^.Station^.Settings.Create(ULINT_TO_STRING(Context.RealTimeClock.TickClock())).Done) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;



IF(Step(inStepID  			:= MaxStepID - 1,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#OPERATIONS COMPLETED#>')) 
THEN
//---------------------------------------
	CompleteSequence();	
//---------------------------------------
END_IF;

// Method: OnStateChange
METHOD PROTECTED OnStateChange
VAR_INPUT
	PreviousState	: INT;
	NewState 		: INT;
END_VAR
IF(NOT __ISVALIDREF(inoComponents)) THEN
	RETURN;
END_IF

inoComponents.Press.Restore();
_gTimer_1(IN := FALSE);

TYPE ST001_Components : STRUCT
    PartPresent : TcoElements.TcoDi(MAIN_TECHNOLOGY._technology._ST001);
    StartButton : TcoElements.TcoDi(MAIN_TECHNOLOGY._technology._ST001);	
    Press : TcoPneumatics.TcoCylinder(MAIN_TECHNOLOGY._technology._ST001);	
	Drive : TcoDriveSimple(MAIN_TECHNOLOGY._technology._ST001);
END_STRUCT
END_TYPE

FUNCTION_BLOCK ST001_ComponentsHandler EXTENDS TcoCore.TcoObject
VAR
	ToMirror:STRING;
	{attribute addProperty Name "<#PART PRESENCE SENSOR#>"}
	_partPresent : TcoElements.TcoDi(THIS^);
	{attribute addProperty Name "<#START BUTTON#>"}
    _startButton : TcoElements.TcoDi(THIS^);
	{attribute addProperty Name "<#PRESS PISTON#>"}
    _press : TcoPneumatics.TcoCylinder(THIS^);
	{attribute addProperty Name "<#ALARM OUTPUT#>"}
	_alarmOutput : TcoElements.TcoDo(THIS^);
	{attribute addProperty Name "<#DRIVE#>"}
	_drive : TcoDrivesBeckhoff.TcoDriveSimple(THIS^);
END_VAR

_partPresent(inoSignal := IO.EC001.A1.IO._1);
_startButton(inoSignal := IO.EC001.A1.IO._2);
_press(inoAtHomePos:= IO.EC001.A1.IO._3, inoAtWorkPos:= IO.EC001.A1.IO._4, inoToHomePos:= IO.EC001.A10.IO._1, inoToWorkPos:=IO.EC001.A10.IO._2);

// Method: Service
METHOD Service
THIS^._partPresent.Service();
THIS^._startButton.Service();
THIS^._press.Service();
THIS^._alarmOutput.Service();

FUNCTION_BLOCK ST001_GroundSequence EXTENDS TcoCore.TcoSequencer
VAR_IN_OUT
	inoComponents : ST001_ComponentsHandler;
END_VAR



// Method: Main
(*~
	<docu>
		<summary>
			Main method of the sequener. Custom code needs to be placed here. The sequencer is executed by call of InstanceName.Run() method.
			This method is abstract, and it must be overridden in derived block.
		</summary>
	</docu>
~*)
METHOD PROTECTED  Main : BOOL
IF(NOT __ISVALIDREF(inoComponents)) THEN
	Messenger.Programming('Invalid reference to inoComponents');
	RETURN;
END_IF


IF(Step(inStepID  			:= 100,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#PRESS IN BASE POSITION#>')) 
THEN
//---------------------------------------
	IF(inoComponents.Press.MoveToHome().Done) THEN
		THIS^.CompleteStep();		
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= 200,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#CHECK PART REMOVAL FROM THE FIXTURE#>')) 
THEN
//---------------------------------------
	IF(inoComponents.PartPresent.IsFalse) THEN
		THIS^.CompleteStep();
	ELSE
		Messenger.Notify('<#Remove part from the fixture please#>');	
	END_IF;
//---------------------------------------
END_IF;

IF(Step(inStepID  			:= MaxStepID - 1,
	    inEnabled 			:= TRUE,
	    inStepDescription 	:= '<#GROUND POSITION COMPLETED#>')) 
THEN
//---------------------------------------
	Messenger.Notify('<#Ground position completed; you can start automat sequence.#>');	
//---------------------------------------
END_IF;

// Method: OnStateChange
METHOD PROTECTED OnStateChange
VAR_INPUT
	PreviousState	: INT;
	NewState 		: INT;
END_VAR
IF(NOT __ISVALIDREF(inoComponents)) THEN
	RETURN;
END_IF

inoComponents.Press.Restore();

