InvalidReference := FALSE;
IF NOT __ISVALIDREF(inoIoData) THEN
	_varInfo :=__VARINFO(inoIoData);
	Messenger.Error(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString());
    InvalidReference := TRUE;
END_IF

