VAR_INPUT
	inValue : BOOL;
END_VAR
_infoTimer(IN := inValue, PT := THIS^.inoConfig.InfoTime);
_errorTimer(IN := inValue, PT := THIS^.inoConfig.ErrorTime);

// Method: OnAbort
(*~
	<docu>
		<summary>
			Executes when task is aborted.
		</summary>			
	</docu>	
~*)
METHOD PROTECTED OnAbort
THIS^.inoStatus.ActionDescription := '<#Trigger was aborted, while not yet completed!#>';

// Method: OnDone
(*~
	<docu>
		<summary>
			Executes when task reaches the ```Done``` state .
		</summary>			
	</docu>	
~*)
METHOD PROTECTED OnDone
THIS^.inoStatus.ActionDescription := '<#Trigger was completed successfully.#>'; 
_progress:=0;

