// Method: Update
METHOD PROTECTED Update
VAR
	_diffToLastSyncInSeconds : LINT;
END_VAR
IF _state = 0 THEN
//	_isValid := FALSE;
	_NT_GetLocalTime(NETID := '127.0.0.1.1.1', START := TRUE);
	IF _NT_GetLocalTime.BUSY AND NOT _NT_GetLocalTime.ERR THEN 
		_state := _state + 10;
	END_IF
END_IF

IF _state = 10 THEN
	_NT_GetLocalTime(START := FALSE);
	IF NOT _NT_GetLocalTime.BUSY AND NOT _NT_GetLocalTime.ERR THEN 
		_state := _state + 10;
	END_IF
END_IF

IF _state = 20 THEN
	_NT_GetLocalTime(START := FALSE);

	_PDT := _NT_GetLocalTime.TIMESTR;

	_isValid := TRUE;
END_IF

_RTC_EX2(EN := _isValid, PDT := _PDT);

_diffToLastSyncInSeconds := ABS(ULINT_TO_LINT(Tc2_EtherCAT.SYSTEMTIME_TO_DCTIME64(_RTC_EX2.CDT,0,0) - Tc2_EtherCAT.SYSTEMTIME_TO_DCTIME64(RtcPrg._LastSyncTimeStampInLocalTime,0,0)))/1000000000;

IF _state >= 20 AND RtcPrg._RtcSynchParams.doSynch AND _diffToLastSyncInSeconds >=RtcPrg._RtcSynchParams.syncPeriod THEN
	_state := 0;
END_IF

_LocalTime := _RTC_EX2.CDT;
_LocalTimeDT := Tc2_EtherCAT.Tc2_Utilities.SYSTEMTIME_TO_DT(_LocalTime);

IF RtcPrg._isSynchronized THEN
	_FB_TzSpecificLocalTimeToSystemTime(in 		:=	_LocalTime,
										tzInfo 	:=	RtcPrg._TimeZoneInformation,
										out		=>	_UTCTime,
										eTzID	=>	_TimeZoneID);
	_UTCTimeDT := Tc2_EtherCAT.Tc2_Utilities.SYSTEMTIME_TO_DT(_UTCTime);
END_IF

