// Method: i_Close
(*~
	<docu>
		<summary>
			Implicit call of this method is ensured by calling the method Run().
			It must not be called explicitely by consumer code in derived blocks.
			<remarks>			
				<note type="important">
					Do not call this method explicitly.
				</note>
			</remarks>
		</summary>			
	</docu>	
~*)
METHOD INTERNAL FINAL i_Close
_lastClosingCycle := Context.StartCycleCount;

IF _sequencerHasError THEN
	OnSequencerError(_sequencerErrorId);
END_IF

_previousNumberOfStepsInSequence := _numberOfStepsInSequence;
Context.Environment.Messaging.Suspend();
IF _modeController._stepIn.Done THEN
	_modeController._stepIn.Restore();	
END_IF
Context.Environment.Messaging.Resume();

_restoringSequence := FALSE;

// Method: i_CompleteSequence
(*~
	<docu>
		<summary>
			<para>
				Completes the sequencer, and return the sequencer pointer to the first step in the seuqence.
				Method is typically called inside the last step of the sequence.
			</para>
		</summary>			
	</docu>	
~*)
METHOD PROTECTED FINAL i_CompleteSequence
_theOrderOfTheCurrentlyExecutedStep := 0;
_LastCycleTime := _SequenceElapsedTime;
_cycleTimer(IN:= FALSE, PT:= T#0S);	

_currentStep.Status := eStepStatus.Done;

OnSequenceCompleted();
OnStepCompleted();
Context.Environment.Messaging.Suspend();
_modeController._stepForward.Restore();
_modeController._stepBackward.Restore();
_modeController._stepIn.Restore(); 	
Context.Environment.Messaging.Resume();

// Method: i_CompleteStep
(*~
	<docu>
		<summary>
			Completes the execution of the current step and moves the sequencer pointer to the next step in order of execution.
			The call returns `ITcoObjectRestorer` that allows to restore object upon step completition.
		</summary>		
		<returns></returns>	
	</docu>	
~*)
METHOD PROTECTED FINAL i_CompleteStep : ITcoObjectRestorer
Messenger.Build().Append('Leaving step id: ').AppendAny(_currentStep.ID).Append(' [').Append(_currentStep.Description).Append('] : ').AppendAny(_theOrderOfTheCurrentlyExecutedStep).As().AsTrace();

_theOrderOfTheCurrentlyExecutedStep := _theOrderOfTheCurrentlyExecutedStep + 1;	
_currentStep.Status := eStepStatus.Done;
OnStepCompleted();
_modeController._stepIn.DoneWhen(_modeController._stepIn.Execute());
i_CompleteStep := THIS^;

// Method: i_Open
(*~
	<docu>
		<summary>
			Implicit calling of this method is ensured by calling the method Run().
			It must not be called explicitely by consumer code in derived blocks.
			<remarks>			
				<note type="important">
					Do not call this method explicitly.
				</note>
			</remarks>
		</summary>			
	</docu>	
~*)
METHOD INTERNAL FINAL i_Open
VAR
	_message	:	STRING(254);
END_VAR
_theOrderOfTheCurrentlyEvaluatedStep := 0;

IF _requestStepActive AND _requestedStepId <> (MinStepID-1) AND (_modeController.Mode <> eSequencerMode.StepMode OR _modeController._stepIn.Busy OR _checkStepIdRequestedInStepMode) THEN
	_requestStepCycle := _requestStepCycle +1;
ELSE
	_requestStepCycle := 0;
END_IF

IF _requestStepCycle > 1 AND NOT _sequencerHasError THEN
	_sequencerErrorId := eSequencerError.StepWithRequestedIdDoesNotExists;
	_message := CONCAT('REQUESTED STEP_ID: ',INT_TO_STRING(_requestedStepId));
	_message := CONCAT(_message, ' DOES NOT EXIST');
	_currentStep.Description := _message;
	_currentStep.Status := eStepStatus.Error;
	THIS^.Messenger.Post(_message, eMessageCategory.ProgrammingError);
	_sequencerHasError := TRUE;
END_IF

IF _StepIdUniquenessControlState = eStepIdUniquenessControlState.NotYetStarted  OR 
	_StepIdUniquenessControlState = eStepIdUniquenessControlState.Requested THEN
	_StepIdUniquenessControlState := eStepIdUniquenessControlState.Started;
END_IF;

_restoringSequence := FALSE;

_lastOpeningCycle := Context.StartCycleCount;

// Method: i_RequestStep
(*~
	<docu>
		<summary>
			Terminates the currently executed step and set the sequencer's pointer to the step with Id that corresponds to ```inRequestedStepID``` parameter.
			When the order of the requested step is higher than the order of the currently finished step (the requested step is "after" the current one)
			the requested step is started in the same context cycle.
			When the order of the requested step is lower than the order of the currently finished step (the requested step is "before" the current one)
			the requested step is started in the next context cycle.
			If the requested step is not found even in the next context cycle, the sequencer enters error state ```StepWithRequestedIdDoesNotExists```.
			<para>
				See <see cref="TcoCore.eSequencerError"/> for detailed description.
			</para>
		</summary>
	</docu>
~*)
METHOD PROTECTED FINAL i_RequestStep : ITcoSequencer
VAR_INPUT
	(*~
		<docu>
			<summary>
				StepId of the step to be executed.
			</summary>
		</docu>
	~*)
	inRequestedStepID : INT := MinStepID-1;
END_VAR
VAR
	_message : STRING(254);
END_VAR
_modeController._stepIn.Restore();

_currentStep.Status := eStepStatus.Done;

_checkStepIdRequestedInStepMode := TRUE;

IF(inRequestedStepID <> (MinStepID-1)) THEN
	IF _requestedStepId <> (MinStepID-1) THEN
		IF NOT  _sequencerHasError THEN
			_sequencerErrorId := eSequencerError.MultipleRequestStepMethodCall;
			_message := CONCAT('REQUESTED STEP_ID: ',INT_TO_STRING(inRequestedStepID));
			_message := CONCAT(_message, ' HAS BEEN REQUIRED, WHILE PREVIOUS REQUESTED STEP_ID: ');
			_message := CONCAT(_message,INT_TO_STRING(_requestedStepId));
			_message := CONCAT(_message, ' HAS NOT BEEN YET PERFORMED!');
			_currentStep.Description := _message;
			_currentStep.Status := eStepStatus.Error;
			THIS^.Messenger.Post(_message, eMessageCategory.ProgrammingError);
			_sequencerHasError := TRUE;
		END_IF
	ELSE
		_requestStepCycle := 0;
		_requestedStepId := inRequestedStepID;
		_requestStepActive := TRUE;
	END_IF
END_IF;	

Messenger.Build().Append('Leaving step id: ').AppendAny(_currentStep.ID).Append(' [').Append(_currentStep.Description).Append('] : ').AppendAny(_theOrderOfTheCurrentlyExecutedStep).As().AsTrace();
Messenger.Build().Append('Reqesting step id jump to: ').AppendAny(inRequestedStepID).As().AsTrace();

i_RequestStep := THIS^;

// Method: i_Step
(*~
	<docu>
		<summary>
				Step of the sequence.
				<note type="important">
					Make sure you do not use the value of `32766` for the step id. This value is reserved for the restore step.
				<note> 
		</summary>					
		<returns>
			True when step with given `StepId` is in order of the execution; the step is enabled and the sequencer is in the cyclic mode.
			True when step with given `StepId` is in order of the execution; the step is enabled, the sequencer is in the step mode and StepIn() method has been triggered.  			
		</returns>			
	</docu>	
~*)
METHOD PROTECTED FINAL i_Step : BOOL
VAR_INPUT
(*~
	<docu>
		<summary>
			StepId of the current step.
			<remarks>			
				<note type="important">
					This number must be unique throughout the complete sequence.
					It must be a constant or numerical literal and it must not change during the life-time of the sequencer. 
				</note>
				<note type="important">
					Make sure you do not use the value of `32766` for the step id. This value is reserved for the restore step.
				<note>				
			</remarks>
		</summary>		
	</docu>	
~*)
	inStepID				: 	INT;
(*~
	<docu>
		<summary>
			If this value is false, step body is not executed and execution is moved to the next enabled step.
		</summary>				
	</docu>	
~*)
	inEnabled				: 	BOOL;
(*~
	<docu>
		<summary>
			Step description text.
		</summary>				
	</docu>	
~*)
	inStepDescription		: 	STRING(254);		
END_VAR
VAR
	_message 				:	STRING(254);	
	_isInOrderOfExecution 	:	BOOL;	
	_stepModeActive 		: 	BOOL;
	_stepInExecuting 		: 	BOOL;
END_VAR
i_Step := FALSE;
IF inStepID < MinStepID THEN
		_message := CONCAT('STEP_ID TOO LOW: ',INT_TO_STRING(inStepID));
		_message := CONCAT(_message, '! MINIMAL VALUE POSSIBLE: ');
		_message := CONCAT(_message,INT_TO_STRING(MinStepID ));
		_message := CONCAT(_message,'!!!');
		_currentStep.Description := _message;
		_currentStep.Status := eStepStatus.Error;
		THIS^.Messenger.Post(_message, eMessageCategory.ProgrammingError);
		_sequencerErrorId := eSequencerError.StepIdTooLow;
		_sequencerHasError := TRUE;
ELSIF  inStepID > MaxStepID THEN
		_message := CONCAT('STEP_ID TOO HIGH: ',INT_TO_STRING(inStepID));
		_message := CONCAT(_message, '! MAXIMAL VALUE POSSIBLE: ');
		_message := CONCAT(_message,INT_TO_STRING(MaxStepID ));
		_message := CONCAT(_message,'!!!');
		_currentStep.Description := _message;
		_currentStep.Status := eStepStatus.Error;
		THIS^.Messenger.Post(_message, eMessageCategory.ProgrammingError);
		_sequencerErrorId := eSequencerError.StepIdTooHigh;
		_sequencerHasError := TRUE;
ELSIF NOT _sequencerHasError THEN
	i_Step := StepInternal(inStepID,inEnabled,inStepDescription);
END_IF;	

Observer.Observe(
	inIsStepActive := i_Step,
	inCurrentStepOrder := _theOrderOfTheCurrentlyExecutedStep,
	inID:= inStepID, 
	inOrder:= _theOrderOfTheCurrentlyEvaluatedStep - 1, 
	inEnabled:= inEnabled, 
	inDescription:= inStepDescription, 
	inStatus:= _currentStep.Status, 
	inDuration:= _currentStep.Duration,
	inStepCount := _numberOfStepsInSequence);

// Method: i_StepCompleteWhen
(*~
	<docu>
		<summary>
			Completes the actually running step, when the `inCondition` parameter is `TRUE`.
			Method is typically called inside a step as the transition method.
		</summary>			
	</docu>	
~*)
METHOD PROTECTED FINAL i_StepCompleteWhen 
VAR_INPUT
(*~
	<docu>
		<summary>
			The condition under which the step is completed.
		</summary>			
	</docu>	
~*)
	inCondition : BOOL;
END_VAR
IF(inCondition) THEN
	THIS^.i_CompleteStep();
END_IF

// Method: IsStepIdUnique
(*~
	<docu>
		<summary>
			Performs the check of the uniqueness of `inStepId` in the sequence.
			<remarks>			
				<note type="important">
					The StepId of each step in the sequence must be unique throughout the complete sequence, and it must not be changed.
				</note>
			</remarks>			
		</summary>				
	</docu>	
~*)
METHOD PRIVATE IsStepIdUnique
VAR_INPUT
(*~
	<docu>
		<summary>
			StepId to be checked for uniqueness.
		</summary>				
	</docu>	
~*)
	inStepID : INT;
END_VAR
VAR
	_i	: UINT;
	_hiIndex : UINT;
	_pUid : INT;
    _pNewSteps : POINTER TO INT;		
	_message : STRING(254);
END_VAR
//Change number of the steps in sequence detected
IF (_numberOfStepsInSequence <> _previousNumberOfStepsInSequence) AND 
	_previousNumberOfStepsInSequence > 0 AND _stepIdUniquenessChecked AND  
	(_StepIdUniquenessControlState = eStepIdUniquenessControlState.NotYetStarted OR _StepIdUniquenessControlState = eStepIdUniquenessControlState.Done) THEN
	_StepIdUniquenessControlState := eStepIdUniquenessControlState.Requested;
END_IF

IF (_StepIdUniquenessControlState >= eStepIdUniquenessControlState.Started AND _StepIdUniquenessControlState < eStepIdUniquenessControlState.Done) THEN

	//If new PLC cycle was performed, step id uniqueness control is done
	IF _StepIdUniquenessControlState = eStepIdUniquenessControlState.Running AND 
  		THIS^.Context.StartCycleCount >= _StepIdUniquenessStartCycleCount + 1 THEN
		_stepIdUniquenessChecked := TRUE;
		_StepIdUniquenessControlState := eStepIdUniquenessControlState.Done;
		_numberOfStepsInSequence := _controlledStepIndex + 1;
	END_IF

	//If step id uniqueness control is finished, clear dynamic arrays 
	IF _StepIdUniquenessControlState >= eStepIdUniquenessControlState.Done THEN 
		IF (_pPreviusSteps <> 0) THEN
			__DELETE(_pPreviusSteps);
		END_IF
		IF (_pNewSteps <> 0) THEN
			__DELETE(_pNewSteps);
		END_IF	
		RETURN;		
	END_IF

	//First call with the very first step of the sequence
	IF _StepIdUniquenessControlState = eStepIdUniquenessControlState.Started THEN
		_StepIdUniquenessStartCycleCount := THIS^.Context.StartCycleCount;
		_controlledStepIndex := 0;

		//It should not exists, if yes delete and create again
		IF (_pPreviusSteps <> 0) THEN
			__DELETE(_pPreviusSteps);
		END_IF
		_pPreviusSteps := __NEW(UINT, 1);
		//Stores first StepId		
		_pPreviusSteps[0] := inStepID;

		_StepIdUniquenessControlState := eStepIdUniquenessControlState.Running;
	ELSIF _StepIdUniquenessControlState = eStepIdUniquenessControlState.Running THEN
		// Increment order of the currently controlled step
		_controlledStepIndex := _controlledStepIndex + 1;

		IF (_pNewSteps <> 0) THEN
			__DELETE(_pNewSteps);
		END_IF
		_pNewSteps := __NEW(UINT, (_controlledStepIndex + 1));

		//Compare with previous Steps and copy previous Steps to new array
		_hiIndex := _controlledStepIndex - 1;
		FOR _i := 0 TO _hiIndex DO
			_pUid := _pPreviusSteps[_i];
			IF inStepID = _pUid THEN
				IF NOT _sequencerHasError THEN
					_sequencerErrorId := eSequencerError.NotUniqueStepId;
					_message := CONCAT('ERROR NOT UNIQUE STEP_ID ',INT_TO_STRING(inStepID));
					_currentStep.Description := _message;
					_currentStep.Status := eStepStatus.Error;
					THIS^.Messenger.Post(_message, eMessageCategory.ProgrammingError);
					_sequencerHasError := TRUE;
					_StepIdUniquenessControlState := eStepIdUniquenessControlState.Error;
					RETURN;					
				END_IF
			ELSE
				_pNewSteps[_i] := _pPreviusSteps[_i];
			END_IF
		END_FOR
		//Store new StepId
		_pNewSteps[_controlledStepIndex] := inStepID;
		//Delete and create again
		IF (_pPreviusSteps <> 0) THEN
			__DELETE(_pPreviusSteps);
		END_IF		
		_pPreviusSteps :=  __NEW(UINT, (_controlledStepIndex+1));
		//Copy
		_hiIndex := _controlledStepIndex;
		FOR _i := 0 TO _hiIndex DO
			_pPreviusSteps[_i] := _pNewSteps[_i];			
		END_FOR

		IF (_pNewSteps <> 0) THEN
			__DELETE(_pNewSteps);
		END_IF
	END_IF	

	_numberOfStepsInSequence := _controlledStepIndex + 1;

END_IF

