VAR_INPUT
END_VAR
VAR_OUTPUT
END_VAR
VAR
	ResetToZero : BOOL := TRUE;
	C1	:	LINT	:= 100;
	C2	:	LINT	:= 200;
	TcoObject_Counter_1 : TcoObject_Counter(THIS^);
	TcoObject_Counter_2 : TcoObject_Counter(THIS^);
	Cycle	:	LINT:=-1;
	TcoTask_DownCounter_1	: TcoTask_DownCounter(THIS^);
	TcoTask_DownCounter_2	: TcoTask_DownCounter(THIS^);
	TcoObject_Counter_1_CountUp_Done_RTRIG : R_TRIG;
	TcoObject_Counter_1_CountDown_Done_RTRIG : R_TRIG;
	TcoObject_Counter_2_CountUp_Done_RTRIG : R_TRIG;
	TcoObject_Counter_2_CountDown_Done_RTRIG : R_TRIG;
	TcoObject_Counter_1_CountUp_Reset : BOOL;
	TcoObject_Counter_1_CountDown_Reset : BOOL;
	TcoObject_Counter_2_CountUp_Reset : BOOL;
	TcoObject_Counter_2_CountDown_Reset : BOOL;
END_VAR

// Method: Main
METHOD PROTECTED  Main
//VAR
//	state : TcoState(THIS^,false); 
//END_VAR
//TcoTaskInvokeLevel();
//TcoTaskInvokeImpulse();
TcoTaskInvokeReset();
//state.Restore(TcoObject_Counter_1.TcoTask_CountUp).Restore(TcoObject_Counter_2.TcoTask_CountUp);

TcoTaskImplementation();

// Method: TcoTaskImplementation
METHOD TcoTaskImplementation
VAR_INPUT
END_VAR
THIS^.TcoTask_DownCounter_1();
//Init Invoke
IF THIS^.TcoTask_DownCounter_1.CounterValue = -1 THEN
	THIS^.TcoTask_DownCounter_1.SetUpValue := C1;
	THIS^.TcoTask_DownCounter_1.Invoke();
END_IF
//Next Invoke during execution
IF	THIS^.TcoTask_DownCounter_1.InTheMiddle THEN
	THIS^.TcoTask_DownCounter_1.SetUpValue := 2 * THIS^.TcoTask_DownCounter_1.SetUpValue;
	THIS^.TcoTask_DownCounter_1.Invoke();
END_IF
//Done and Invoke again
IF THIS^.TcoTask_DownCounter_1.Done THEN
	THIS^.TcoTask_DownCounter_1.SetUpValue := C1;
	THIS^.TcoTask_DownCounter_1.Invoke();
END_IF

THIS^.TcoTask_DownCounter_2();
//Init Invoke
IF THIS^.TcoTask_DownCounter_2.CounterValue = -1 THEN
	THIS^.TcoTask_DownCounter_2.SetUpValue := C2;
	THIS^.TcoTask_DownCounter_2.Invoke();
END_IF
//Next Invoke during execution
IF	THIS^.TcoTask_DownCounter_2.InTheMiddle THEN
	THIS^.TcoTask_DownCounter_2.SetUpValue := 2 * THIS^.TcoTask_DownCounter_2.SetUpValue;
	THIS^.TcoTask_DownCounter_2.Invoke();
END_IF
//Done and Invoke again
IF THIS^.TcoTask_DownCounter_2.Done THEN
	THIS^.TcoTask_DownCounter_2.SetUpValue := C2;
	THIS^.TcoTask_DownCounter_2.Invoke();
END_IF

// Method: TcoTaskInvokeImpulse
METHOD TcoTaskInvokeImpulse
VAR_INPUT
END_VAR
TcoObject_Counter_1();

TcoObject_Counter_2();

TcoObject_Counter_1_CountUp_Done_RTRIG(CLK := THIS^.TcoObject_Counter_1.TcoTask_CountUp.Done );
TcoObject_Counter_1_CountDown_Done_RTRIG(CLK := THIS^.TcoObject_Counter_1.TcoTask_CountDown.Done );
TcoObject_Counter_2_CountUp_Done_RTRIG(CLK := THIS^.TcoObject_Counter_2.TcoTask_CountUp.Done );
TcoObject_Counter_2_CountDown_Done_RTRIG(CLK := THIS^.TcoObject_Counter_2.TcoTask_CountDown.Done );


IF ResetToZero THEN
	THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Invoke();
	THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Invoke();
	ResetToZero := FALSE;
END_IF

IF THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Done THEN
	THIS^.TcoObject_Counter_1.StartCountUp(C1);
	THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Restore();	//ResetToZeroTask has to be reseted, otherwise StartCountUp is called cyclically
END_IF;

IF THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Done THEN
	THIS^.TcoObject_Counter_2.StartCountUp(C2);
	THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Restore(); //ResetToZeroTask has to be reseted, otherwise StartCountUp is called cyclically
END_IF;

IF TcoObject_Counter_1_CountUp_Done_RTRIG.Q THEN
	THIS^.TcoObject_Counter_1.StartCountDown(-C1);
END_IF;

IF TcoObject_Counter_2_CountUp_Done_RTRIG.Q THEN
	THIS^.TcoObject_Counter_2.StartCountDown(-C2);
END_IF;

IF THIS^.TcoObject_Counter_1.TcoTask_CountDown.Done AND NOT THIS^.TcoObject_Counter_1.TcoTask_CountUp.Busy
	AND THIS^.TcoObject_Counter_2.TcoTask_CountDown.Done AND NOT THIS^.TcoObject_Counter_2.TcoTask_CountUp.Busy THEN
	THIS^.TcoObject_Counter_1.StartCountUp(C1);
	THIS^.TcoObject_Counter_2.StartCountUp(C2);
END_IF

Cycle	:= THIS^.TcoObject_Counter_2.Cycle ;

// Method: TcoTaskInvokeLevel
METHOD TcoTaskInvokeLevel
VAR_INPUT
END_VAR
TcoObject_Counter_1();

TcoObject_Counter_2();

IF ResetToZero THEN
	THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Invoke();
	THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Invoke();
	ResetToZero := FALSE;
END_IF

IF THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Done THEN
	THIS^.TcoObject_Counter_1.StartCountUp(C1);
	THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Restore();	//ResetToZeroTask has to be reseted, otherwise StartCountUp is called cyclically
END_IF;

IF THIS^.TcoObject_Counter_1.TcoTask_CountUp.Done THEN
	THIS^.TcoObject_Counter_1.StartCountDown(-C1);
END_IF;

IF THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Done THEN
	THIS^.TcoObject_Counter_2.StartCountUp(C2);
	THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Restore(); //ResetToZeroTask has to be reseted, otherwise StartCountUp is called cyclically
END_IF;

IF THIS^.TcoObject_Counter_2.TcoTask_CountUp.Done THEN
	THIS^.TcoObject_Counter_2.StartCountDown(-C2);
END_IF;

IF THIS^.TcoObject_Counter_1.TcoTask_CountDown.Done AND THIS^.TcoObject_Counter_2.TcoTask_CountDown.Done THEN
	THIS^.TcoObject_Counter_1.StartCountUp(C1);
	THIS^.TcoObject_Counter_2.StartCountUp(C2);
END_IF

Cycle	:= THIS^.TcoObject_Counter_2.Cycle ;

// Method: TcoTaskInvokeReset
METHOD TcoTaskInvokeReset
VAR_INPUT
END_VAR
TcoObject_Counter_1();

TcoObject_Counter_2();

TcoObject_Counter_1_CountUp_Reset 	:= FALSE;
TcoObject_Counter_1_CountDown_Reset := False;
TcoObject_Counter_2_CountUp_Reset 	:= False;
TcoObject_Counter_2_CountDown_Reset := False;

THIS^.TcoObject_Counter_1.TcoTask_ResetToZero.Invoke();
THIS^.TcoObject_Counter_2.TcoTask_ResetToZero.Invoke();
THIS^.TcoObject_Counter_1.StartCountUp(C1);
THIS^.TcoObject_Counter_1.StartCountDown(-C1);
THIS^.TcoObject_Counter_2.StartCountUp(C2);
THIS^.TcoObject_Counter_2.StartCountDown(-C2);

IF THIS^.TcoObject_Counter_1.TcoTask_CountUp.Busy THEN
	THIS^.TcoObject_Counter_1.TcoTask_CountDown.Restore();
	TcoObject_Counter_1_CountDown_Reset := TRUE;
END_IF

IF THIS^.TcoObject_Counter_2.TcoTask_CountUp.Busy THEN
	THIS^.TcoObject_Counter_2.TcoTask_CountDown.Restore();
	TcoObject_Counter_2_CountDown_Reset := TRUE;
END_IF

IF THIS^.TcoObject_Counter_2.TcoTask_CountDown.Busy THEN
	THIS^.TcoObject_Counter_1.TcoTask_CountUp.Restore();
	TcoObject_Counter_1_CountUp_Reset := TRUE;
END_IF


IF THIS^.TcoObject_Counter_2.TcoTask_CountDown.Busy THEN
	THIS^.TcoObject_Counter_2.TcoTask_CountUp.Restore();
	TcoObject_Counter_2_CountUp_Reset := TRUE;
END_IF

Cycle	:= THIS^.TcoObject_Counter_2.Cycle ;

FUNCTION_BLOCK TcoObject_Counter EXTENDS TcoCore.TcoObject
VAR
	CounterValue : LINT;
	UpperLimit : LINT;
	LowerLimit : LINT;
	TcoTask_CountUp : TcoCore.TcoTask(THIS^);
	TcoTask_CountDown : TcoCore.TcoTask(THIS^);
	TcoTask_ResetToZero : TcoCore.TcoTask(THIS^);
	CountUp_InvokeTrigCounter : LINT;
	CountUp_DoneTrigCounter : LINT;
	CountDown_InvokeTrigCounter : LINT;
	CountDown_DoneTrigCounter : LINT;
	ResetToZero_InvokeTrigCounter : LINT;
	ResetToZero_DoneTrigCounter : LINT;
	CountUp_PreviousState : TcoCore.eTaskState;
	CountDown_PreviousState : TcoCore.eTaskState;
	ResetToZero_PreviousState : TcoCore.eTaskState;
	CountUp_Execute : BOOL;
	CountDown_Execute : BOOL;
	ResetToZero_Execute : BOOL;
	CountUp_Busy : BOOL;
	CountDown_Busy : BOOL;
	ResetToZero_Busy : BOOL;
	CountUp_Done : BOOL;
	CountDown_Done : BOOL;
	ResetToZero_Done : BOOL;
	Cycle	:LINT ;

END_VAR

CountUp_Execute 	:= FALSE;
CountDown_Execute 	:= FALSE;
ResetToZero_Execute := FALSE;
CountUp_Busy 		:= FALSE;
CountDown_Busy 		:= FALSE;
ResetToZero_Busy 	:= FALSE;
CountUp_Done 		:= FALSE;
CountDown_Done 		:= FALSE;
ResetToZero_Done 	:= FALSE;

//******************************************************************
IF(TcoTask_CountUp._taskState = eTaskState.Requested AND CountUp_PreviousState<> eTaskState.Requested ) THEN
	CountUp_InvokeTrigCounter := CountUp_InvokeTrigCounter + 1;
END_IF

IF(TcoTask_CountUp.Execute()) THEN
	CountUp_Busy 		:= TRUE;
	CounterValue := CounterValue + 1;
	TcoTask_CountUp.DoneWhen(CounterValue >= UpperLimit);			
END_IF

IF(TcoTask_CountUp._taskState = eTaskState.Done AND CountUp_PreviousState <> eTaskState.Done ) THEN
	CountUp_DoneTrigCounter := CountUp_DoneTrigCounter + 1;
END_IF
CountUp_Done 		:= TcoTask_CountUp._taskState = eTaskState.Done;
CountUp_PreviousState := TcoTask_CountUp._taskState ;
//******************************************************************

//******************************************************************
IF(TcoTask_CountDown._taskState = eTaskState.Requested AND CountDown_PreviousState <> eTaskState.Requested) THEN
	CountDown_InvokeTrigCounter := CountDown_InvokeTrigCounter + 1;
END_IF

IF(TcoTask_CountDown.Execute()) THEN
	CountDown_Busy 		:= TRUE;
	CounterValue := CounterValue - 1;
	TcoTask_CountDown.DoneWhen(CounterValue <= LowerLimit);			
END_IF

IF(TcoTask_CountDown._taskState = eTaskState.Done AND CountDown_PreviousState <> eTaskState.Done) THEN
	CountDown_DoneTrigCounter := CountDown_DoneTrigCounter + 1;
	Cycle	:= Cycle +1 ;
END_IF
CountDown_Done 		:= TcoTask_CountDown._taskState = eTaskState.Done;
CountDown_PreviousState := TcoTask_CountDown._taskState ;
//******************************************************************

//******************************************************************
IF (TcoTask_ResetToZero._taskState = eTaskState.Requested AND ResetToZero_PreviousState <> eTaskState.Requested) THEN
	ResetToZero_InvokeTrigCounter := ResetToZero_InvokeTrigCounter + 1;
END_IF

IF(TcoTask_ResetToZero.Execute()) THEN	
	ResetToZero_Busy 	:= TRUE;
	TcoTask_ResetToZero.DoneWhen(TRUE);	
END_IF

IF (TcoTask_ResetToZero._taskState = eTaskState.Done AND ResetToZero_PreviousState <> eTaskState.Done) THEN
	ResetToZero_DoneTrigCounter := ResetToZero_DoneTrigCounter + 1;
END_IF
ResetToZero_Done 	:= TcoTask_ResetToZero._taskState = eTaskState.Done;
ResetToZero_PreviousState := TcoTask_ResetToZero._taskState;
//******************************************************************

// Method: Restore
METHOD Restore : BOOL
VAR_INPUT
END_VAR
TcoTask_CountUp.Restore();
TcoTask_CountDown.Restore();
CounterValue := 0;

ResetToZero_Execute := TRUE;

THIS^.TcoTask_ResetToZero.Invoke();

// Method: StartCountDown
METHOD StartCountDown
VAR_INPUT
	Value : LINT;
END_VAR
THIS^.LowerLimit := Value;

CountDown_Execute 	:= TRUE;

TcoTask_CountDown.Invoke();

// Method: StartCountUp
METHOD StartCountUp
VAR_INPUT
	Value : LINT;
END_VAR
THIS^.UpperLimit := Value;

CountUp_Execute 	:= TRUE;

TcoTask_CountUp.Invoke();

