	_s.StepCompleteWhen(_vertical.MoveDown().Done);
//-----------------------------------------------------	
END_IF

IF(_s.Step(700, 
		TRUE, 
		'OPEN GRIPPER')) THEN
//-----------------------------------------------------
	_s.StepCompleteWhen(_gripper.Open().Done);
//-----------------------------------------------------	
END_IF

IF(_s.Step(800, 
		TRUE, 
