	_tcoTaskTest_B			:	TcoTaskTest(THIS^);
	_tcoStateTest_A			:	TcoStateTest(THIS^, eRestoreMode.AutoRestoreMembers);
	_tcoStateTest_B			:	TcoStateTest(THIS^, eRestoreMode.None);
	// Object equality
