// Method: SetTestParams
METHOD INTERNAL SetTestParams
VAR_INPUT
	inRunOneStep		:	BOOL;
	inRunAllSteps		:	BOOL;
	inFinishStep		:	BOOL;
	inID				:	UINT;
	inEnabled			:	BOOL;
	inStepDescription	:	STRING(254);	
END_VAR
THIS^._runOneStep		:=			inRunOneStep;
THIS^._runAllSteps 		:= 			inRunAllSteps;
THIS^._finishStep 		:= 			inFinishStep;
THIS^._stepId 				:=			inID;
THIS^._enabled 			:= 			inEnabled;
THIS^._stepDescription 	:=			inStepDescription;

// Method: StepCount
METHOD StepCount 
VAR_INPUT
    inTotalStepNumber : UINT;
    inFinishStep : BOOL;
END_VAR
VAR 
	i : INT;
	_lastStepId : INT;
END_VAR
FOR i:=0 TO inTotalStepNumber DO
	IF SUPER^.Step(i,TRUE,CONCAT('Step number ',INT_TO_STRING(i))) THEN		
		SUPER^.StepCompleteWhen(inFinishStep);	
	END_IF	
END_FOR

// Method: UpdateCurrentStepDetails
{attribute 'TcRpcEnable'}
METHOD INTERNAL UpdateCurrentStepDetails
_currentStepId				:=	SUPER^._currentStep.ID;
_currentStepOrder			:=	SUPER^._currentStep.Order;
_currentStepEnabled			:=	SUPER^._currentStep.Enabled;
_currentStepDescription		:=	SUPER^._currentStep.Description;
_currentStepStatus			:=	SUPER^._currentStep.Status;
_currentStepDuration		:=	SUPER^._currentStep.Duration;

FUNCTION_BLOCK TcoSequencerTestChildState EXTENDS TcoCore.TcoState
VAR
	_requestedState : UINT;
	_requestedStateCount :ULINT;
	_restoreCount :ULINT;
END_VAR

// Method: OnStateChange
(*~
	<docu>
		<summary>
			This method is called on each change of the <c>State</c>. This method could be overloaded and custom code should be placed here.	
		</summary>			
	</docu>	
~*)
METHOD PROTECTED OnStateChange
VAR_INPUT
	PreviousState	: INT;
	NewState 		: INT;
END_VAR
IF NewState =  _requestedState THEN
	_requestedStateCount := _requestedStateCount + 1;
END_IF

IF NewState =  -1 THEN
	_restoreCount := _restoreCount + 1;
END_IF

