FUNCTION_BLOCK TcoStateAutoRestoreTest EXTENDS TcoState
VAR
	_myState						:	INT;	
	_onStateChangeCounter			:	INT;	
	_restoreCounter					:	INT;	
	_autoRestoreToMyChildsEnabled	: 	BOOL;
	_autoRestoreByMyParentEnabled	: 	BOOL;	
