END_VAR

// Method: CleanUp
{attribute 'TcRpcEnable'}
METHOD INTERNAL CleanUp
THIS^.ChangeState(0);
_myState := State;	
_onStateChangeCounter			:= 0;
_restoreCounter					:= 0;
_autoRestoreToMyChildsEnabled	:= FALSE;
_autoRestoreByMyParentEnabled	:= FALSE;
_countsPerStep					:= 0;
_counterValue					:= 0;

// Method: ExecutionBody
{attribute 'TcRpcEnable'}
METHOD INTERNAL ExecutionBody
IF State =-1 THEN
	_counterValue := 0;	
	ChangeState(0);
END_IF

IF State = 0 THEN
	_counterValue := _counterValue + 1;	
	IF (_counterValue MOD _countsPerStep) = 0 THEN
		ChangeState(State + 10);
	END_IF
END_IF

IF State = 10 THEN
	_counterValue := _counterValue + 1;	
	IF (_counterValue MOD _countsPerStep) = 0 THEN
		ChangeState(State + 10);
	END_IF
END_IF

IF State = 20 THEN
	_counterValue := _counterValue + 1;	
	IF (_counterValue MOD _countsPerStep) = 0 THEN
		ChangeState(State + 10);
	END_IF
END_IF

IF State = 30 THEN
	_counterValue := _counterValue + 1;	
	IF (_counterValue MOD _countsPerStep) = 0 THEN
		ChangeState(State + 10);
	END_IF
END_IF

IF State = 40 THEN
	_counterValue := _counterValue + 1;	
	IF (_counterValue MOD _countsPerStep) = 0 THEN
		ChangeState(State + 10);
	END_IF
END_IF

IF State = 50 THEN
	_counterValue := _counterValue + 1;	
	IF (_counterValue MOD _countsPerStep) = 0 THEN
		ChangeState(State + 10);
	END_IF
END_IF

IF State = 60 THEN
	ChangeState(-1);
END_IF

_myState := State;

