	_inspectionsEmpty         : ARRAY[0..LAST_INSPECTION_INDEX] OF ULINT;
    _inspectionIndex          : INT;
    _tierAct                  : TcoCore.TcoTier(THIS^);
    _normalizedAllowedRetries : UINT;


