// Method: Act
(*~
	<summary>
		Initiates grouped inspection.
	</summary>
~*)
METHOD Act : ITcoInspectionGroup
//VAR_IN_OUT
//	inoResult : TcoComprehensiveResult;
//END_VAR
OverInspected := FALSE;
_inspectionIndex          := 0;
_done                     := TRUE; // True then set to false if any inspector not done.
_normalizedAllowedRetries := MAX_NORMALIZED_RETRIES;
Act := THIS^;



IF (_tierAct.IsNewTier()) THEN
	_inspections:=_inspectionsEmpty;
    ClearResult(_currentRunResult);
END_IF

// Method: ClearResult
METHOD ClearResult
VAR_IN_OUT
	inoResult : TcoComprehensiveResult;
END_VAR
inoResult.ErrorCodes := '';
inoResult.Failures := '';
inoResult.Result := eOverallResult.NoAction;

// Method: Dialog
METHOD Dialog : BOOL
VAR_INPUT
	inRetryStep : INT;
END_VAR
IF(THIS^.Done) THEN
	_tcoInspectorDialogue.OverInspected := THIS^.OverInspected;		
	IF(THIS^._currentRunResult.Result = eOverallResult.Failed) THEN
		THIS^._tcoInspectorDialogue.Invoke();
		_tcoInspectorDialogue();	

		{warning disable C0357}
		IF(_tcoInspectorDialogue._dialogRetry) THEN			
			Retry(inRetryStep);			
		END_IF

		IF(_tcoInspectorDialogue._dialogTerminate) THEN
			Terminate();
		END_IF

		IF(_tcoInspectorDialogue._dialogOverride) THEN
			CarryOn();
		END_IF
		{warning enable C0357}
	ELSE
		IF(Coordinator <> 0) THEN
			Coordinator.MoveNext();
		END_IF;	
	END_IF;	
END_IF;

// Method: DialogWithExternalClose
METHOD DialogWithExternalClose : BOOL
VAR_INPUT
	inRetryStep : INT;
	inRetrySignal:BOOL;
	inTerminateSignal : BOOL;
END_VAR
//IF THIS^._tcoInspectorDialogue.State=eTaskState.Ready THEN
//	THIS^._tcoInspectorDialogue.DialogRetry 	    :=  FALSE;	
//	THIS^._tcoInspectorDialogue.DialogTerminate  	:=  FALSE;	
//	THIS^._tcoInspectorDialogue.DialogOverride   	:=  FALSE;
//END_IF




_tcoInspectorDialogue.HandleExternalSignals(inRetrySignal:=inRetrySignal,inTerminateSignal:=inTerminateSignal);


IF(THIS^.Done) THEN
	_tcoInspectorDialogue.OverInspected := THIS^.OverInspected;		
	IF(THIS^._currentRunResult.Result = eOverallResult.Failed) THEN
		THIS^._tcoInspectorDialogue.Invoke();
		_tcoInspectorDialogue();	


		{warning disable C0357}
		IF(_tcoInspectorDialogue._dialogRetry AND _tcoInspectorDialogue.DialogIsClosed ) THEN			
			Retry(inRetryStep);	

		END_IF

		IF(_tcoInspectorDialogue._dialogTerminate AND _tcoInspectorDialogue.DialogIsClosed ) THEN
			Terminate();
		END_IF

		IF(_tcoInspectorDialogue._dialogOverride AND _tcoInspectorDialogue.DialogIsClosed) THEN
			CarryOn();
		END_IF
		{warning enable C0357}
	ELSE
		IF(Coordinator <> 0) THEN
			Coordinator.MoveNext();
		END_IF;	
	END_IF;	
END_IF;

IF THIS^._tcoInspectorDialogue.State=eTaskState.Done 
		AND ( _tcoInspectorDialogue.DialogRetry
		OR _tcoInspectorDialogue.DialogTerminate
		OR _tcoInspectorDialogue.DialogOverride)
		AND _tcoInspectorDialogue.DialogIsClosed  THEN	
	THIS^._tcoInspectorDialogue.Restore();
END_IF;

// Method: Evaluate
(*~
	<docu>
		<summary>
			Upon failure the inspection retries given number of time. When it reach	given numbers then terminate 		
		</summary>			
	</docu>	
~*)

{attribute 'hide'}
{attribute 'obsolete' := 'You should access `Evaluate` method via `OnFail()` method.'}
METHOD PUBLIC Evaluate : BOOL
VAR_INPUT
    (*~
	<docu>
		<summary>
			State from which the inspection will restart.		
		</summary>			
	</docu>	
	~*)
    inFromState : INT;
    (*~
	<docu>
		<summary>
			Behavior when ispection is failed		
		</summary>			
	</docu>	
	~*)
    inFailMode : eTcoInspectorFailMode;
    (*~
	<docu>
		<summary>
			State from which the inspection will continue.		
		</summary>			
	</docu>	
	~*)
    inToState : INT;
END_VAR
IF (_coordinator = 0) THEN
    RETURN;
END_IF

IF (THIS^.Done) THEN
    IF (THIS^._currentRunResult.Result = eOverallResult.Failed) THEN
        IF (__ISVALIDREF(_refOverallResult)) THEN
            _refOverallResult := _originalOverallResult;
        END_IF

        IF inFailMode = eTcoInspectorFailMode.CarryOn THEN
            _coordinator.MoveNext();
        ELSIF inFailMode = eTcoInspectorFailMode.JumpTo THEN
            _coordinator.Retry(inToState);
        ELSIF inFailMode = eTcoInspectorFailMode.Terminate THEN
            _coordinator.Terminate();
        ELSIF inFailMode = eTcoInspectorFailMode.RetryThenCarryOn THEN
            IF OverInspected THEN
                _coordinator.MoveNext();
            ELSE
                _coordinator.Retry(inFromState);
            END_IF;
        ELSIF inFailMode = eTcoInspectorFailMode.RetryThenJumpTo THEN
            IF OverInspected THEN
                _coordinator.Retry(inToState);
            ELSE
                _coordinator.Retry(inFromState);
            END_IF;

        ELSIF inFailMode = eTcoInspectorFailMode.RetryThenTeminate THEN
            IF OverInspected THEN
                _coordinator.Terminate();
            ELSE
                _coordinator.Retry(inFromState);
            END_IF;

        END_IF
    ELSE

        _coordinator.MoveNext();
    END_IF;
END_IF;

Evaluate := THIS^.Done;

// Method: Inspect
(*~
	<summary>
		Add inspector to inspection group to inspect
	</summary>
~*)
METHOD Inspect : ITcoInspectionGroup
VAR_INPUT
    Inspector : IInspector;
END_VAR
OnEnterInspection();

IF(_normalizedAllowedRetries <> 0 
AND _normalizedAllowedRetries <> MAX_NORMALIZED_RETRIES) THEN
	Inspector.CommonData.NumberOfAllowedRetries := _normalizedAllowedRetries;
END_IF;

Inspect := THIS^;


IF(Inspector.OverInspected) THEN
	THIS^.OverInspected := TRUE;
END_IF;

IF (Inspector.Done) THEN
    Inspector.UpdateComprehensiveResult(_currentRunResult);							
ELSE
	_done := FALSE;	
	_done_PV := FALSE;	
END_IF


IF(_inspectionIndex < LAST_INSPECTION_INDEX)THEN
	_inspections[_inspectionIndex] :=  Inspector.Identity;
	_inspectionIndex := _inspectionIndex + 1;
END_IF

// Method: NormalizeRetries
(*~
	<summary>
		Sets lower `number of allowed retries` for this call of inspection group.
		Invoke this method multiple times if you want to check for the inspection for lowest numebr of retries.
		<note type="important">
			The inspections will run at least once before allowed entries is normalized.
		</note>
	</summary>
~*)

METHOD NormalizeRetries : ITcoInspectionGroup
VAR_INPUT
	inoInspection : IInspector;
END_VAR
// Determine lowest number of retries
NormalizeRetries := THIS^;
IF( inoInspection.CommonData.NumberOfAllowedRetries <> 0 
AND_THEN inoInspection.CommonData.NumberOfAllowedRetries < _normalizedAllowedRetries) THEN
	_normalizedAllowedRetries := inoInspection.CommonData.NumberOfAllowedRetries;
END_IF

// Method: OnFail
METHOD OnFail : IOnFail
VAR_INPUT
END_VAR
//THIS^._tcoInspectorDialogue.SetInspector(THIS^);
OnFail := THIS^;

// Method: Retry
{attribute 'hide'}
{attribute 'obsolete' := 'You should access `Retry` method via `OnFail()` method.'}
METHOD Retry : BOOL
VAR_INPUT
	inFromState : INT;
END_VAR
IF(_coordinator = 0) THEN
	RETURN;	
END_IF

IF(THIS^.Done) THEN
	IF(THIS^._currentRunResult.Result = eOverallResult.Failed) THEN		
		IF(__ISVALIDREF(_refOverallResult)) THEN
			_refOverallResult := _originalOverallResult;
		END_IF	 
		ClearResult(_currentRunResult);	   	
		_coordinator.Retry(inFromState);
	ELSE
		_coordinator.MoveNext();
	END_IF;	
END_IF;	


Retry := THIS^.Done;

// Method: RetryThenTerminate
{attribute 'hide'}
{attribute 'obsolete' := 'You should access `RetryThenTerminate` method via `OnFail()` method.'}
METHOD RetryThenTerminate : BOOL
VAR_INPUT
	inFromState : INT;
END_VAR
IF (_coordinator = 0) THEN
    RETURN;
END_IF

IF (THIS^.Done) THEN
    IF (THIS^._currentRunResult.Result = eOverallResult.Failed) THEN
        IF (__ISVALIDREF(_refOverallResult)) THEN
            _refOverallResult := _originalOverallResult;
        END_IF

        ClearResult(_currentRunResult);
        IF OverInspected THEN
            _coordinator.Terminate();
        ELSE
            _coordinator.Retry(inFromState);
        END_IF;
    ELSE
        _coordinator.MoveNext();
    END_IF;
END_IF;

RetryThenTerminate := THIS^.Done;

// Method: Terminate
{attribute 'hide'}
{attribute 'obsolete' := 'You should access `Terminate` method via `OnFail()` method.'}
METHOD Terminate : BOOL
IF(_coordinator = 0) THEN
	RETURN;	
END_IF

IF(THIS^.Done) THEN
	IF(THIS^._currentRunResult.Result = eOverallResult.Failed) THEN
		_coordinator.Terminate();
	ELSE
		_coordinator.MoveNext();
	END_IF;	
END_IF;	

Terminate := THIS^.Done;

// Method: UpdateComprehensiveResult
(*~
	<docu>
		<summary>
			Updates comprehensive result. The comprehensive result is set to `Failed` when any inspection fails or is inconclusive.
			Any bypassed or excluded inspection are not taken in the account.			
		</summary>			
	</docu>	
~*)

METHOD UpdateComprehensiveResult : IInspector
VAR_IN_OUT
	(*~
	<docu>
		<summary>
			Comprehensive result data structure to be updated.	
		</summary>			
	</docu>	
	~*)
    inoResult : TcoComprehensiveResult;
END_VAR
UpdateComprehensiveResult := THIS^;

_refOverallResult REF= inoResult;

IF(_tierUpdateOverall.IsNewTier()) THEN	
	_originalOverallResult := inoResult;
END_IF


CASE _currentRunResult.Result OF
	eOverallResult.NoAction:
		;
	eOverallResult.Passed:
		;
	eOverallResult.Failed:

		_refOverallResult.Result		:= eOverallResult.Failed;
		_refOverallResult.Failures		:= _currentRunResult.Failures;
		_refOverallResult.ErrorCodes	:= _currentRunResult.ErrorCodes;
END_CASE


IF(_done) THEN
	_overallResult := _refOverallResult;
END_IF;

// Method: UpdateDescriptions
(*~
	<docu>
		<summary>
			Updates failure description. Adding `FailureDescription` do the overall result structure.
		</summary>	
	</docu>	
~*)
METHOD PROTECTED UpdateDescriptions
VAR_IN_OUT
	inoResult : TcoComprehensiveResult;
END_VAR
IF NOT _done THEN
	_done_PV := FALSE;	
END_IF
IF(_done AND NOT _done_PV) THEN
	inoResult.Failures := THIS^.Context.Environment.Messaging.StringBuilder.Clear()
				.Append(inoResult.Failures)				
				.Append(CommonData.FailureDescription)
				.Append(';')
				.ToString();

	inoResult.ErrorCodes := THIS^.Context.Environment.Messaging.StringBuilder.Clear()
				.Append(inoResult.ErrorCodes)				
				.Append(CommonData.ErrorCode)
				.Append(';')
				.ToString();			
	_done_PV := TRUE;	
END_IF;

