// Method: IsOverinspected
(*~
	<docu>
		<summary>
			Gets `true` when this inspection overruns max number of inspection.
		</summary>			
	</docu>	
~*)
METHOD PROTECTED IsOverinspected : BOOL
_isOverInspected := THIS^.OverInspected;
