	THIS^._inspectorTask.Invoke();
	IF(THIS^._inspectorTask.Execute()) THEN		
		THIS^._inspectorTask.InspectionData.Result := eInspectorResult.Failed;
		THIS^._inspectorTask.DoneWhen(TRUE);	
	END_IF	
END_IF

