FUNCTION_BLOCK DriveSimMoveAbsoluteTask EXTENDS TcoCore.TcoTask
VAR_IN_OUT
	_drive : DriveSim;
END_VAR

VAR
	{attribute addProperty Name "<#Target position#>"}
	_targetPosition : LREAL;
END_VAR

IF(Execute())THEN
	Messenger.Debug('Moving absolute');
	IF(_drive.Position < _targetPosition) THEN
		_drive.Position := _drive._position + 1;
	ELSE
		_drive.Position := _drive._position - 1;
	END_IF;	
	DoneWhen(ABS(_drive._position - THIS^.TargetPosition) < 2);	
END_IF

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE enumModes :
(
	Idle := 0,
	Automat := 1000,
	Ground := 2000,
	Service := 3000
);
END_TYPE

{attribute wpf [Container(Layout.Wrap)]}
{attribute wpf [Group(Layout.GroupBox)]}
TYPE AnalogueValueCheck :
STRUCT
	Mininum : REAL;
	{attribute clr [RenderIgnore("ShadowControl", "ShadowControlSlim")]}
	Measured : REAL;
	Maximum : REAL;	
END_STRUCT
END_TYPE

FUNCTION_BLOCK Checkers EXTENDS TcoCore.TcoObject
VAR
	_result : eCheckResult;
END_VAR

// Method: CheckAnalogue
METHOD CheckAnalogue : REFERENCE TO Checkers
VAR_INPUT
	Signal : REAL;
END_VAR
VAR_INPUT
	pData : POINTER TO AnalogueValueCheck;
END_VAR
VAR
	_inRange : BOOL;
END_VAR
pData^.Measured := Signal;
_inRange := (Signal >= pData^.Mininum) AND (Signal <= pData^.Maximum);

IF(NOT _inRange 
AND_THEN _result <= eCheckResult.Passed) THEN
	_result := eCheckResult.Failed;
END_IF; 

CheckAnalogue REF= THIS^;

// Method: HasPassed
METHOD HasPassed : BOOL
VAR_INPUT
END_VAR
HasPassed := _result = eCheckResult.Passed;
_result := eCheckResult.None;

// Method: StartChecks
METHOD StartChecks : REFERENCE TO Checkers
VAR_INPUT
END_VAR
_result := eCheckResult.Passed;
StartChecks REF= THIS^;

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE eCheckResult :
(
	None   := 0,
	Passed := 10,
	Failed := 20
);
END_TYPE

