    {attribute 'hide'} 
	_infoTimer :  TON;
	_infoTime:TIME;
    {attribute 'hide'} 
	_errorTimer :  TON;
	_errorTime:	TIME;
	{attribute 'hide'} 
	_timer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
	{attribute 'hide'} 
	_autoRestore : BOOL;

END_VAR

// Method: CallTimers
METHOD CallTimers
VAR_INPUT
	inValue : BOOL;
END_VAR
IF THIS^.ErrorTime <> T#0S OR NOT inValue THEN  
_errorTimer(IN := inValue, PT := THIS^.ErrorTime);
END_IF;
IF THIS^.InfoTime <>T#0S OR NOT inValue THEN  
_infoTimer(IN := inValue, PT := THIS^.InfoTime);
END_IF;

// Method: Restore
(*~
	<docu>
		<summary>
			Restores this instance to the Ready state. Can be called explicitly or from within one of the restore mechanisms.
			<para>
				See also <see cref="PlcDocu.TcoCore.TcoTask.AutoRestorable()"/>
			</para>
		</summary>			
	</docu>	
~*)
METHOD Restore : ITcoRestorable
SUPER^.Restore();
_progress := 0;
_timer(In:=FALSE);
CallTimers(FALSE);
Messenger.UnPin();
_errorMessage.UnPin();
_autoRestore:=false;

FUNCTION_BLOCK TcoTixonBufferTask EXTENDS TcoTixonFeedingTask
VAR_IN_OUT
	inoConfig 	: TcoTixonGenericConfig;
   	inoControl 	: TcoTixonGenericControl;
	inoStatus 	: TcoTixonGenericStatus;	
END_VAR

IF Execute() THEN


    IF _progress = 0 THEN
        IF NOT __ISVALIDREF(inoControl) THEN
            _varInfo := __VARINFO(inoControl);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoConfig) THEN
            _varInfo := __VARINFO(inoConfig);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoStatus) THEN
            _varInfo := __VARINFO(inoStatus);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT inoStatus.ControllerInAuto THEN
            _varInfo := __VARINFO(inoStatus.ControllerInAuto);
            Messenger.Warning(_sb.Clear().Append('<#Tixon control system not in auto #>').Append(_varInfo.Symbol).ToString());
        ELSE
			IF NOT THIS^._errorMessage.Pinned THEN	
           		_progress := _progress + 1;
			END_IF;

        END_IF

    END_IF
  	IF _progress = 1 THEN
        Messenger.Debug('<#Waiting for buffer is Empty #>');
        _timer(IN := NOT inoStatus.FillingSensor OR (inoStatus.SeparatorHomePos AND NOT inoStatus.SeparatorPresent),
            Pt := inoConfig.BufferEmptyTime);

        IF _timer.Q THEN
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;


    END_IF;
    IF _progress = 2 THEN
        Messenger.Debug('<#Waiting for blow on #>');
        _timer(IN :=TRUE,
            Pt := inoConfig.BufferBlowStartTime);
		  inoControl.BlowAValve := inoConfig.BufferBlowActive;

        IF _timer.Q OR NOT inoConfig.BufferBlowActive THEN  
			inoControl.FeedingA:=TRUE;
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;


    END_IF;


    IF _progress = 3 THEN
        Messenger.Debug('<#Waiting for buffer is full and go idle#>');
        _timer(IN := inoStatus.FillingSensor AND InoStatus.SeparatorPresent, Pt := inoConfig.BufferIdleTime);

        IF _timer.Q THEN
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF
    END_IF;

    IF _progress = 4 THEN
        inoControl.FeedingA := FALSE;
        Messenger.Debug('<#Waiting for buffer is full and blow ending#>');
        _timer(IN := TRUE, Pt := inoConfig.BufferBlowFullTime);
        IF _timer.Q OR NOT inoConfig.BufferBlowActive THEN
            inoControl.BlowAValve := FALSE;
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;

    END_IF;

    IF _progress = 5 THEN
        THIS^.DoneWhen(TRUE);
    END_IF;

    CallTimers(_progress>1);//empty and start feeding

    THIS^.ThrowWhen(_errorTimer.Q);

END_IF

IF THIS^.Error AND NOT _errorMessage.Pinned THEN
    THIS^.Restore();
END_IF

// Method: OnAbort
(*~
	<docu>
		<summary>
			Executes when task is aborted.
		</summary>			
	</docu>	
~*)
METHOD PROTECTED OnAbort
IF  __ISVALIDREF(inoStatus) THEN   THIS^.inoStatus.ActionDescription := '<#Buffer task  was aborted.#>'; END_IF;

// Method: OnDone
(*~
	<docu>
		<summary>
			Executes when task reaches the ```Done``` state .
		</summary>			
	</docu>	
~*)
METHOD PROTECTED OnDone
IF  __ISVALIDREF(inoStatus) THEN   THIS^.inoStatus.ActionDescription := '<#Buffer task  finished successfully.#>'; END_IF;
_progress:=0;
IF AutoRestore THEN
	Restore();
END_IF

// Method: OnError
METHOD PROTECTED OnError
VAR
	description: STRING;
END_VAR
description := '<#Buffer task finished with error.#>'; 
inoControl.FeedingA:=FALSE;
inoControl.BlowAValve:=false;
IF  __ISVALIDREF(inoStatus) THEN   THIS^.inoStatus.ActionDescription := description; END_IF;
THIS^._errorMessage.Error(_sb.Clear().Append(description).Append(' To restore acknowledge this alarm.').ToString()).Pin();

// Method: OnStart
METHOD PROTECTED OnStart
IF  __ISVALIDREF(inoStatus) THEN  THIS^.inoStatus.ActionDescription := '<#Buffer task started.#>'; END_IF; 

CallTimers(FALSE);

// Method: Restore
(*~
	<docu>
		<summary>
			Restores this instance to the Ready state. Can be called explicitly or from within one of the restore mechanisms.
			<para>
				See also <see cref="PlcDocu.TcoCore.TcoTask.AutoRestorable()"/>
			</para>
		</summary>			
	</docu>	
~*)
METHOD Restore : ITcoRestorable
SUPER^.Restore();

