FUNCTION TcoDintToBytes
VAR_INPUT
	inFormat : eTcoDataFormat;
	inValue : DINT;
END_VAR
VAR_IN_OUT
    outByte0: BYTE;
    outByte1: BYTE;
    outByte2: BYTE;
    outByte3: BYTE;
END_VAR
VAR
	_b0: BYTE;
	_b1: BYTE;
	_b2: BYTE;
    _b3: BYTE;

	_tmpDINT : DINT; 
END_VAR

_tmpDINT:=inValue;

_b3:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);
_b2:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);
_b1:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);
_b0:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);

IF inFormat=eTcoDataFormat.LittleEndian THEN
	outByte0 := _b3;
	outByte1 := _b2;	
	outByte2 := _b1;
	outByte3 := _b0;	
ELSIF inFormat=eTcoDataFormat.BigEndian THEN
	outByte0 := _b0;
	outByte1 := _b1;	
	outByte2 := _b2;
	outByte3 := _b3;	
END_IF

FUNCTION TcoIntToBytes 
VAR_INPUT
	inFormat : eTcoDataFormat;
	inValue : INT;
END_VAR
VAR_IN_OUT
    outByte0: BYTE;
    outByte1: BYTE;
END_VAR
VAR
	_b0: BYTE;
	_b1: BYTE;

	_tmpINT : INT; 
END_VAR

_tmpINT:=inValue;

_b1:=UDINT_TO_BYTE(_tmpINT MOD 256);
_tmpINT:=SHR(_tmpINT,8);
_b0:=UDINT_TO_BYTE(_tmpINT MOD 256);
_tmpINT:=SHR(_tmpINT,8);

IF inFormat=eTcoDataFormat.LittleEndian THEN
	outByte0 := _b1;
	outByte1 := _b0;	
ELSIF inFormat=eTcoDataFormat.BigEndian THEN
	outByte0 := _b0;
	outByte1 := _b1;	
END_IF

FUNCTION TcoRealToBytes
VAR_INPUT
    inFormat : eTcoDataFormat;
    inValue : REAL;
END_VAR
VAR_IN_OUT
    outByte0 : BYTE;
    outByte1 : BYTE;
    outByte2 : BYTE;
    outByte3 : BYTE;
END_VAR
VAR
    _b0 : BYTE;
    _b1 : BYTE;
    _b2 : BYTE;
    _b3 : BYTE;

    _tmpReal : REAL;
    _rExponent : LREAL;
    _Exponent : DINT;
    _Fraction : DINT;
    _tmpDINT : DINT;
END_VAR

IF (inValue <= -EXPT(2, 128)) OR (inValue >= EXPT(2, 128)) THEN
    outByte0 := 0;
    outByte1 := 0;
    outByte2 := 0;
    outByte3 := 0;
    return;
END_IF

IF inValue < 0 THEN
    _tmpReal := ABS(inValue);
    _rExponent := LOG(_tmpReal) / LOG(2);

    IF _rExponent >= 0 THEN
        _Exponent := TRUNC(_rExponent);

    ELSE
        _Exponent := TRUNC(_rExponent) - 1;
    END_IF

    _Fraction := REAL_TO_DINT((_tmpReal / EXPT(2, _Exponent) - 1) * 8388608);

    _tmpDINT := ANY_TO_DINT(2147483648 + (_Exponent + 127) * 8388608 + _Fraction);

ELSIF inValue > 0 THEN
    _tmpReal := ABS(inValue);
    _rExponent := LOG(_tmpReal) / LOG(2);

    IF _rExponent >= 0 THEN
        _Exponent := TRUNC(_rExponent);
    ELSE
        _Exponent := TRUNC(_rExponent) - 1;
    END_IF

    _Fraction := REAL_TO_DINT((_tmpReal / EXPT(2, _Exponent) - 1) * 8388608);
    _tmpDINT := ANY_TO_DINT((_Exponent + 127) * 8388608 + _Fraction);
ELSE
    _tmpDINT := 0;
END_IF

_b3 := UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT := SHR(_tmpDINT, 8);
_b2 := UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT := SHR(_tmpDINT, 8);
_b1 := UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT := SHR(_tmpDINT, 8);
_b0 := UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT := SHR(_tmpDINT, 8);

IF inFormat = eTcoDataFormat.LittleEndian THEN
    outByte0 := _b3;
    outByte1 := _b2;
    outByte2 := _b1;
    outByte3 := _b0;
ELSIF inFormat = eTcoDataFormat.BigEndian THEN
    outByte0 := _b0;
    outByte1 := _b1;
    outByte2 := _b2;
    outByte3 := _b3;
END_IF

FUNCTION TcoUdintToBytes
VAR_INPUT
