TYPE BitStruct :
STRUCT
    bBit0  : BIT;
	bBit1  : BIT;
    bBit2  : BIT;
    bBit3  : BIT;
    bBit4  : BIT;
    bBit5  : BIT;
    bBit6  : BIT;
    bBit7  : BIT;
END_STRUCT
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE eTcoConversionTests :
(
	None := 0,
	Init := 10,
	TcoBytesToReal := 20,
	TcoRealToBytes := 30,
	TcoBytesToRealPlcArrange := 40,
	TcoRealToBytesPlcArrange := 50
);
END_TYPE

TYPE floatUnion :
UNION
	value:REAL;
	bytes:ARRAY[0..3] OF BYTE;
	bits:ARRAY[0..3] OF BitStruct;
END_UNION
END_TYPE

FUNCTION_BLOCK TcoConversionTetsContext EXTENDS TcoCore._internals_TcoContext
VAR
	_Byte0: BYTE;
    _Byte1: BYTE;
    _Byte2: BYTE;
    _Byte3: BYTE;
	_realValue:REAL;
	_format: TcoUtilities.eTcoDataFormat;
	_resultRealValue:REAL;
	_resultByte0:BYTE;
	_resultByte1:BYTE;
	_resultByte2:BYTE;
	_resultByte3:BYTE;
	_tcoConversionTestDone: BOOL;
	_union :floatUnion;
END_VAR

// Method: Main
METHOD PROTECTED Main
VAR

END_VAR
CASE THIS^._testId OF
	eTcoConversionTests.None :
	eTcoBlinkerTestList.Init :
		_Byte0:=0;
		_Byte1:=0;
		_Byte2:=0;
		_Byte3:=0;
		_resultByte0:=0;
		_resultByte1:=0;
		_resultByte2:=0;
		_resultByte3:=0;
		_realValue:=0;
		_resultRealValue:=0;
		_tcoConversionTestDone := FALSE;
		_union.value:=0;

	eTcoConversionTests.TcoBytesToReal :			
		_resultRealValue:= TcoBytesToReal(_format,_byte0,_byte1,_byte2,_byte3);
	eTcoConversionTests.TcoRealToBytes :			
		TcoRealToBytes(_format,_realValue,_resultByte0,_resultByte1,_resultByte2,_resultByte3);
	eTcoConversionTests.TcoBytesToRealPlcArrange :	
		_union.value:= _realValue;
		IF _format = TcoUtilities.eTcoDataFormat.LittleEndian THEN
			_resultRealValue:= TcoBytesToReal(_format,_union.bytes[0],_union.bytes[1],_union.bytes[2],_union.bytes[3]);
		ELSE
			_resultRealValue:= TcoBytesToReal(_format,_union.bytes[3],_union.bytes[2],_union.bytes[1],_union.bytes[0]);
		END_IF;
	eTcoConversionTests.TcoRealToBytesPlcArrange :	
		_union.value:= _realValue;
		IF _format = TcoUtilities.eTcoDataFormat.LittleEndian THEN
			TcoRealToBytes(_format,_realValue,_resultByte0,_resultByte1,_resultByte2,_resultByte3);
		ELSE
			TcoRealToBytes(_format,_realValue,_resultByte3,_resultByte2,_resultByte1,_resultByte0);
		END_IF;

END_CASE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE eTcoBlinkerTestList :
(
	None := 0,
	Init := 10,
	TcoBlinker := 20
);
END_TYPE

FUNCTION_BLOCK TcoBlinkerTestContext EXTENDS TcoCore._internals_TcoContext
VAR
	_tcoBlinker : TcoUtilities.TcoBlinker(THIS^);
	_tcoBlinkerOnTime : TIME;
	_tcoBlinkerOffTime : TIME;
	_tcoBlinkerOnTimeDuration : TIME;
	_tcoBlinkerOffTimeDuration : TIME;
	_tcoBlinkerTestTimerOn : Tc2_Standard.TON;
	_tcoBlinkerTestTimerOff : Tc2_Standard.TON;
	_tcoBlinkerTestTimerOverall : Tc2_Standard.TON;
	_tcoBlinkerTestDone : BOOL;
END_VAR

// Method: Main
METHOD PROTECTED Main
CASE THIS^._testId OF
	eTcoBlinkerTestList.None :
	eTcoBlinkerTestList.Init :
		_tcoBlinkerTestTimerOn(IN := FALSE);
		_tcoBlinkerTestTimerOff(IN := FALSE);
		_tcoBlinkerTestTimerOverall(IN := FALSE);
		_tcoBlinkerTestDone := FALSE;
	eTcoBlinkerTestList.TcoBlinker :			
		_tcoBlinker(inOnTime := _tcoBlinkerOnTime, inOffTime := _tcoBlinkerOffTime);			

		_tcoBlinkerTestTimerOn(IN := _tcoBlinker.outQ, PT := T#10D);
		_tcoBlinkerTestTimerOff(IN := NOT _tcoBlinker.outQ, PT := T#10D);

		IF(_tcoBlinker.IsOn) THEN
			_tcoBlinkerOnTimeDuration := _tcoBlinkerTestTimerOn.ET;	
		END_IF

		IF(_tcoBlinker.IsOff) THEN
			_tcoBlinkerOffTimeDuration := _tcoBlinkerTestTimerOff.ET;	
		END_IF		



		_tcoBlinkerTestTimerOverall(IN := TRUE, PT := _tcoBlinkerOnTime + _tcoBlinkerOffTime + T#10MS, Q => _tcoBlinkerTestDone);

		IF(_tcoBlinkerTestDone) THEN
			THIS^._testId := 0;
		END_IF
END_CASE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE eTcoEvaluateMeasurementTestList :
(
	None := 0,
	Init := 10,
	Evaluate := 20

);
END_TYPE

FUNCTION_BLOCK TcoEvaluateMeasurementContext EXTENDS TcoCore._internals_TcoContext
VAR
	_tcoMeasEvaluator : TcoUtilities.TcoEvaluateMeasurementTask(THIS^);
	_entityId :STRING;

	_tcoMeasEvaluatorConfig :TcoUtilities.TcoEvaluateMeasurementConfig;
	_measData: ARRAY [0..1000] OF TcoUtilities.TcoEvaluateMeasurementDataItem;
	_tcoEvaluateTestDone: BOOL;


END_VAR

// Method: Main
METHOD PROTECTED Main
VAR
	_cleanData:ARRAY [0..1000] OF TcoEvaluateMeasurementDataItem;	
END_VAR
_tcoMeasEvaluator();
CASE THIS^._testId OF
    eTcoEvaluateMeasurementTestList.None:
        ;
    eTcoEvaluateMeasurementTestList.Init:
		_tcoEvaluateTestDone:=FALSE;
		_measData:=_cleanData;
        _tcoMeasEvaluator.Restore();
    eTcoEvaluateMeasurementTestList.Evaluate:
        _tcoEvaluateTestDone := _tcoMeasEvaluator.Run(inEntityId:=_entityId ,inConfig := _tcoMeasEvaluatorConfig, inData := _measData).Invoke().Done;

        IF (_tcoEvaluateTestDone) THEN
            THIS^._testId := 0;
        END_IF
END_CASE
